/* TeamFinder's small, framework-free client: all state-changing actions call the REST API. */
(() => {
  'use strict';
  const API = localStorage.getItem('teamfinder.apiBase') || 'http://localhost:8080/api';
  const $ = (s, root = document) => root.querySelector(s);
  const app = $('#app');
  const page = document.body.dataset.page;
  const token = () => localStorage.getItem('teamfinder.token');
  const user = () => { try { return JSON.parse(localStorage.getItem('teamfinder.user')); } catch { return null; } };
  const isAdmin = () => user()?.role === 'ADMIN';
  const esc = (value = '') => String(value ?? '').replace(/[&<>'"]/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[ch]));
  const initials = name => String(name || 'Student').split(/\s+/).slice(0, 2).map(x => x[0]).join('').toUpperCase();
  const nice = value => String(value || '').toLowerCase().split('_').map(x => x ? x[0].toUpperCase() + x.slice(1) : '').join(' ');
  const query = () => new URLSearchParams(location.search);
  const qs = params => { const s = new URLSearchParams(); Object.entries(params).forEach(([k,v]) => { if (v !== undefined && v !== null && v !== '') s.set(k, v); }); return s.toString(); };
  const go = href => { location.href = href; };

  async function api(path, options = {}) {
    const headers = { Accept: 'application/json', ...(options.headers || {}) };
    if (token()) headers.Authorization = `Bearer ${token()}`;
    if (options.body && !(options.body instanceof FormData)) headers['Content-Type'] = 'application/json';
    let response;
    try { response = await fetch(`${API}${path}`, { ...options, headers }); }
    catch { throw new Error('The API could not be reached. Start the backend and check the address in README.md.'); }
    const data = response.status === 204 ? null : await response.json().catch(() => null);
    if (!response.ok) {
      if (response.status === 401) { signOut(false); if (!['login','register','landing'].includes(page)) go('login.html'); }
      const message = data?.message || 'The request could not be completed.';
      const error = new Error(message); error.fields = data?.fieldErrors || {}; error.status = response.status; throw error;
    }
    return data;
  }
  function saveAuth(data) { localStorage.setItem('teamfinder.token', data.token); localStorage.setItem('teamfinder.user', JSON.stringify(data.user)); }
  function signOut(redirect = true) { localStorage.removeItem('teamfinder.token'); localStorage.removeItem('teamfinder.user'); if (redirect) go('index.html'); }
  function toast(message, type = 'success') {
    const host = $('#toasts'); if (!host) return;
    const node = document.createElement('div'); node.className = `toast align-items-center border-0 text-bg-${type === 'success' ? 'success' : type === 'danger' ? 'danger' : 'primary'}`;
    node.setAttribute('role','status'); node.innerHTML = `<div class="d-flex"><div class="toast-body">${esc(message)}</div><button type="button" class="btn-close btn-close-white me-2 m-auto" data-bs-dismiss="toast" aria-label="Close"></button></div>`;
    host.append(node); const instance = new bootstrap.Toast(node,{delay:4200}); node.addEventListener('hidden.bs.toast',()=>node.remove()); instance.show();
  }
  function busy() { app.innerHTML = `<div class="loading-block"><span class="loading-spinner" aria-label="Loading"></span><span class="mt-3">Loading the latest information…</span></div>`; }
  function setButtonBusy(button, busyState, label = 'Saving…') { if (!button) return; button.disabled = busyState; if (busyState) { button.dataset.label = button.innerHTML; button.innerHTML = `<span class="spinner-border spinner-border-sm me-2"></span>${label}`; } else button.innerHTML = button.dataset.label || button.innerHTML; }
  function showError(error, form) { if (form) { form.querySelectorAll('.is-invalid').forEach(x => x.classList.remove('is-invalid')); Object.entries(error.fields || {}).forEach(([key,msg]) => { const input = form.querySelector(`[name="${CSS.escape(key)}"]`); if (input) { input.classList.add('is-invalid'); let feedback = input.parentElement.querySelector('.invalid-feedback'); if (feedback) feedback.textContent = msg; } }); } toast(error.message || 'Something went wrong.', 'danger'); }
  function requireAuth(admin = false) { if (!token() || !user()) { go('login.html'); return false; } if (admin && !isAdmin()) { go('unauthorized.html'); return false; } return true; }

  function nav() {
    const node = $('#site-nav'); if (!node) return; const current = page;
    const item = (href,label,activePages=[]) => `<li class="nav-item"><a class="nav-link ${activePages.includes(current)?'active':''}" href="${href}">${label}</a></li>`;
    if (!user()) { node.innerHTML = `<div class="container"><a class="navbar-brand" href="index.html"><span class="brand-mark"><i class="bi bi-people-fill"></i></span>TeamFinder</a><button class="navbar-toggler" type="button" data-bs-toggle="collapse" data-bs-target="#nav"><span class="navbar-toggler-icon"></span></button><div class="collapse navbar-collapse" id="nav"><ul class="navbar-nav ms-auto align-items-lg-center gap-lg-1">${item('projects.html','Explore projects',['projects','project'])}<li class="nav-item"><a class="btn btn-sm btn-outline-light ms-lg-2" href="login.html">Sign in</a></li><li class="nav-item"><a class="btn btn-sm btn-teal ms-lg-2" href="register.html">Create account</a></li></ul></div></div>`; return; }
    const adminLink = isAdmin() ? item('admin.html','Admin',['admin','admin-users','admin-projects']) : '';
    node.innerHTML = `<div class="container"><a class="navbar-brand" href="${isAdmin()?'admin.html':'dashboard.html'}"><span class="brand-mark"><i class="bi bi-people-fill"></i></span>TeamFinder</a><button class="navbar-toggler" type="button" data-bs-toggle="collapse" data-bs-target="#nav"><span class="navbar-toggler-icon"></span></button><div class="collapse navbar-collapse" id="nav"><ul class="navbar-nav ms-auto align-items-lg-center gap-lg-1">${item('dashboard.html','Dashboard',['dashboard'])}${item('projects.html','Explore',['projects','project'])}${!isAdmin()?item('create-project.html','Create project',['create-project','edit-project','candidates']):''}${!isAdmin()?item('invitations.html','Invitations',['invitations']):''}${adminLink}<li class="nav-item dropdown ms-lg-2"><button class="btn btn-sm nav-user dropdown-toggle" data-bs-toggle="dropdown"><span class="me-1">${esc(initials(user().fullName))}</span>${esc(user().fullName.split(' ')[0])}</button><ul class="dropdown-menu dropdown-menu-end shadow border-0"><li><a class="dropdown-item" href="profile.html"><i class="bi bi-person me-2"></i>My profile</a></li><li><a class="dropdown-item" href="edit-profile.html"><i class="bi bi-pencil-square me-2"></i>Edit profile</a></li><li><hr class="dropdown-divider"></li><li><button class="dropdown-item text-danger" id="logout"><i class="bi bi-box-arrow-right me-2"></i>Sign out</button></li></ul></li></ul></div></div>`;
    $('#logout')?.addEventListener('click', () => { api('/auth/logout',{method:'POST'}).catch(()=>{}).finally(()=>signOut()); });
  }
  function footer() { const node=$('#site-footer'); if(node) node.innerHTML=`<div class="container d-flex flex-column flex-md-row gap-2 justify-content-between"><span>© ${new Date().getFullYear()} TeamFinder · Academic projects made more collaborative.</span><span><a href="projects.html">Explore projects</a> · <a href="login.html">Sign in</a></span></div>`; }
  const head = (title, text, action = '') => `<section class="page-head"><div class="container d-flex flex-column flex-md-row align-items-md-end justify-content-between gap-3"><div><p class="section-label mb-2">Student Project Team Finder</p><h1 class="mb-2">${esc(title)}</h1><p>${esc(text)}</p></div>${action}</div></section>`;
  const avatar = (name, tone = '') => `<span class="avatar ${tone}" aria-label="${esc(name)}">${esc(initials(name))}</span>`;
  const status = value => `<span class="badge status-${String(value||'').toLowerCase()}">${esc(nice(value))}</span>`;
  const skills = values => (values || []).map(s => `<span class="skill-chip ${s.skillType ? s.skillType.toLowerCase():''}">${esc(s.name || s)}</span>`).join('');
  const empty = (icon,title,text,action='') => `<div class="surface empty-state"><i class="bi bi-${icon}" aria-hidden="true"></i><h3>${esc(title)}</h3><p class="mb-3">${esc(text)}</p>${action}</div>`;
  const projectCard = p => `<article class="card project-card"><div class="card-body"><div class="d-flex justify-content-between gap-2 align-items-start mb-3"><span class="section-label">${esc(p.category)}</span>${status(p.status)}</div><h3>${esc(p.title)}</h3><p>${esc(p.shortDescription)}</p><div class="mt-auto pt-3"><div class="mb-2">${skills(p.skills?.slice(0,4))}</div><div class="d-flex justify-content-between project-meta mb-3"><span><i class="bi bi-people me-1"></i>${p.currentTeamSize}/${p.teamSize} members</span><span>${esc(p.ownerName)}</span></div><a href="project.html?id=${p.id}" class="btn btn-soft btn-sm">View project <i class="bi bi-arrow-right ms-1"></i></a></div></div></article>`;
  const projectsGrid = list => list?.length ? `<div class="row g-3">${list.map(p=>`<div class="col-md-6 col-xl-4">${projectCard(p)}</div>`).join('')}</div>` : empty('people','No projects match yet','Try widening the filters or create the first project.','<a class="btn btn-primary" href="create-project.html">Create a project</a>');
  const pageNumbers = result => result.totalPages > 1 ? `<nav aria-label="Project pages"><ul class="pagination justify-content-center mt-4">${Array.from({length:result.totalPages},(_,i)=>`<li class="page-item ${i===result.number?'active':''}"><button class="page-link" data-page-number="${i}">${i+1}</button></li>`).join('')}</ul></nav>` : '';

  function landing() {
    app.innerHTML = `<section class="hero"><div class="container"><div class="row align-items-center g-5"><div class="col-lg-8"><span class="eyebrow"><i class="bi bi-stars"></i> Built for meaningful academic collaboration</span><h1 class="display-title mt-3 mb-4">Find the people who can move your project forward.</h1><p class="hero-lede mb-4">TeamFinder helps students discover project opportunities, make skill-aware introductions, and keep project work visible from first idea to final delivery.</p><div class="d-flex gap-2"><a class="btn btn-teal" href="register.html">Start building your team <i class="bi bi-arrow-right ms-1"></i></a><a class="btn btn-outline-light" href="projects.html">Explore open projects</a></div></div><div class="col-lg-4"><div class="hero-card"><p class="text-uppercase fw-bold small text-info mb-3">A clearer way to form teams</p><div class="row text-center"><div class="col-4 hero-stat"><strong>80%</strong><span>required-skill weight</span></div><div class="col-4 hero-stat"><strong>15%</strong><span>preferred skills</span></div><div class="col-4 hero-stat"><strong>5%</strong><span>domain interest</span></div></div></div></div></div></div></section><section class="section-pad"><div class="container"><div class="row align-items-end mb-4"><div class="col-lg-7"><p class="section-kicker mb-2">Thoughtful team formation</p><h2 class="section-title">Built around the work students actually need to do.</h2></div><div class="col-lg-5"><p class="text-secondary mb-0">From open project discovery to clear milestones, every screen supports practical collaboration instead of another generic student feed.</p></div></div><div class="row g-3"><div class="col-md-4"><article class="card feature-card"><div class="card-body"><div class="feature-icon"><i class="bi bi-person-check"></i></div><h3>Skill-aware discovery</h3><p>Search by capability, branch, year, and availability. Profiles make it easy to understand what someone can contribute.</p></div></article></div><div class="col-md-4"><article class="card feature-card"><div class="card-body"><div class="feature-icon teal"><i class="bi bi-diagram-3"></i></div><h3>Explainable matches</h3><p>Project owners see an honest match score with the skills that align and the gaps that still need coverage.</p></div></article></div><div class="col-md-4"><article class="card feature-card"><div class="card-body"><div class="feature-icon warm"><i class="bi bi-flag"></i></div><h3>Momentum after forming</h3><p>Keep roles, milestones, progress, and recent activity in one shared team workspace.</p></div></article></div></div></div></section><section class="pb-5"><div class="container"><div class="callout d-flex flex-column flex-md-row justify-content-between gap-3 align-items-md-center"><div><strong class="d-block mb-1">Ready to turn a good idea into a good team?</strong><span>Set up a profile in a few minutes, then explore projects that genuinely need your strengths.</span></div><a href="register.html" class="btn btn-primary flex-shrink-0">Create your student profile</a></div></div></section>`;
  }

  function authPage(mode) {
    const login = mode === 'login'; document.body.innerHTML = `<main class="auth-shell"><aside class="auth-aside"><a class="navbar-brand text-white" href="index.html"><span class="brand-mark"><i class="bi bi-people-fill"></i></span>TeamFinder</a><div class="mt-5"><span class="eyebrow">Academic collaboration, made practical</span><h1 class="display-6 fw-bold mt-3">${login?'Welcome back to the work that matters.':'Your next capable teammate may already be on campus.'}</h1><p class="mt-3 text-light-emphasis">Build teams around real skills, shared interests, and clear availability — then give that team a focused place to work.</p></div></aside><section class="auth-form-wrap"><div class="auth-form"><a class="auth-logo d-lg-none" href="index.html"><span class="brand-mark"><i class="bi bi-people-fill"></i></span>TeamFinder</a><p class="section-label mt-4 mb-2">${login?'Sign in':'Join your campus network'}</p><h1 class="auth-title">${login?'Good to see you.':'Create your profile.'}</h1><p class="text-secondary mb-4">${login?'Use your TeamFinder account to continue.':'Start with the essentials; you can add skills and interests next.'}</p>${login?loginForm():registerForm()}</div></section></main>`;
  }
  const loginForm = () => `<form id="login-form" novalidate><div class="mb-3"><label class="form-label" for="email">University email</label><input class="form-control" id="email" name="email" type="email" autocomplete="email" required><div class="invalid-feedback">Enter a valid email address.</div></div><div class="mb-3"><label class="form-label" for="password">Password</label><input class="form-control" id="password" name="password" type="password" autocomplete="current-password" required><div class="invalid-feedback">Enter your password.</div></div><button class="btn btn-primary w-100" type="submit">Sign in</button><div class="development-note mt-4"><strong>Development account</strong><br>Student: <code>arjun@campus.dev</code> · Password: <code>CampusPass!2026</code><br>Admin: <code>admin@campus.dev</code> · Password: <code>CampusPass!2026</code></div><p class="text-center text-secondary small mt-4 mb-0">New here? <a href="register.html">Create a student account</a></p></form>`;
  const registerForm = () => `<form id="register-form" novalidate><div class="row g-3"><div class="col-12"><label class="form-label" for="fullName">Full name</label><input class="form-control" id="fullName" name="fullName" autocomplete="name" required><div class="invalid-feedback">Please enter your name.</div></div><div class="col-12"><label class="form-label" for="email">University email</label><input class="form-control" id="email" name="email" type="email" autocomplete="email" required><div class="invalid-feedback">Please enter a valid email.</div></div><div class="col-md-7"><label class="form-label" for="branch">Department or branch</label><input class="form-control" id="branch" name="branch" placeholder="e.g. Computer Science" required><div class="invalid-feedback">Add your department or branch.</div></div><div class="col-md-5"><label class="form-label" for="academicYear">Academic year</label><select class="form-select" id="academicYear" name="academicYear" required><option value="">Choose</option>${[1,2,3,4,5].map(x=>`<option value="${x}">Year ${x}</option>`).join('')}</select><div class="invalid-feedback">Choose your academic year.</div></div><div class="col-12"><label class="form-label" for="password">Password</label><input class="form-control" id="password" name="password" type="password" autocomplete="new-password" minlength="8" required><div class="form-text">Use at least 8 characters.</div><div class="invalid-feedback">Use a password with at least 8 characters.</div></div></div><button class="btn btn-primary w-100 mt-4" type="submit">Create student account</button><p class="text-center text-secondary small mt-4 mb-0">Already have an account? <a href="login.html">Sign in</a></p></form>`;
  function bindAuth(mode) { const form = $(`#${mode}-form`); form?.addEventListener('submit', async e => { e.preventDefault(); if (!form.checkValidity()) { form.classList.add('was-validated'); return; } const button=$('button[type="submit"]',form); setButtonBusy(button,true,mode==='login'?'Signing in…':'Creating account…'); try { const d=new FormData(form); const body=Object.fromEntries(d.entries()); if(mode==='register'){body.academicYear=Number(body.academicYear);body.role='STUDENT';} const response=await api(`/auth/${mode}`,{method:'POST',body:JSON.stringify(body)}); saveAuth(response); go(response.user.role==='ADMIN'?'admin.html':mode==='register'?'edit-profile.html':'dashboard.html'); }catch(err){showError(err,form);}finally{setButtonBusy(button,false);} }); }

  async function dashboard() { if(!requireAuth())return; busy(); try { const d=await api('/dashboard'); app.innerHTML = `${head(`Hello, ${d.profile.fullName.split(' ')[0]}`, 'A quick view of your active project work and the opportunities waiting for you.','<a class="btn btn-primary" href="create-project.html"><i class="bi bi-plus-lg me-1"></i>Create project</a>')}<section class="page-main"><div class="container"><div class="row g-3 mb-4"><div class="col-sm-6 col-xl-3">${metric('bi-briefcase','Projects you lead',d.ownedProjects.length,'')}</div><div class="col-sm-6 col-xl-3">${metric('bi-people','Teams you joined',d.teamProjects.length,'success')}</div><div class="col-sm-6 col-xl-3">${metric('bi-envelope','Pending invitations',d.invitations.filter(x=>x.status==='PENDING').length,'warning')}</div><div class="col-sm-6 col-xl-3">${metric('bi-person-check','Profile complete',`${d.profile.profileCompletion}%`,'')}</div></div><div class="row g-4"><div class="col-lg-8"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h5 section-title mb-0">Your projects</h2><a href="projects.html" class="small fw-bold">Explore all projects</a></div>${d.ownedProjects.length||d.teamProjects.length?projectsGrid([...d.ownedProjects,...d.teamProjects]):empty('briefcase','No project work yet','Create a project post or browse the open opportunities.')}</div><aside class="col-lg-4"><div class="surface p-3 mb-3"><div class="d-flex align-items-center gap-3"><div>${avatar(d.profile.fullName,'teal')}</div><div><div class="fw-bold">${esc(d.profile.fullName)}</div><div class="small text-secondary">${esc(d.profile.branch)} · Year ${d.profile.academicYear}</div></div></div><div class="d-flex justify-content-between align-items-center mt-3"><span class="small text-secondary">Profile completion</span><span class="profile-completion">${d.profile.profileCompletion}%</span></div><div class="progress profile-progress mt-2"><div class="progress-bar" style="width:${d.profile.profileCompletion}%"></div></div><a class="btn btn-soft btn-sm mt-3" href="edit-profile.html">Improve profile</a></div><h2 class="h6 section-title mb-3">Open opportunities</h2>${d.openProjects.length?d.openProjects.slice(0,3).map(p=>`<a href="project.html?id=${p.id}" class="surface d-flex gap-2 p-3 mb-2 text-body"><span class="feature-icon"><i class="bi bi-lightbulb"></i></span><span><strong class="d-block small">${esc(p.title)}</strong><span class="small text-secondary">${esc(p.category)} · ${p.remainingSlots} slots left</span></span></a>`).join(''):empty('search','Nothing open right now','Check back soon.')}</aside></div></div></section>`; } catch(e){renderFailure(e);} }
  const metric = (icon,label,value,tone) => `<div class="surface metric-card d-flex align-items-center gap-3"><div class="metric-icon ${tone}"><i class="bi ${icon}"></i></div><div><div class="metric-value">${esc(value)}</div><div class="metric-label">${esc(label)}</div></div></div>`;

  async function profile() { if(!requireAuth())return; busy(); try { const d=await api('/students/me'); app.innerHTML=`${head('Your profile','The information teammates see before they choose to collaborate.','<a class="btn btn-primary" href="edit-profile.html"><i class="bi bi-pencil-square me-1"></i>Edit profile</a>')}<section class="page-main"><div class="container"><div class="row g-4"><div class="col-lg-4"><div class="surface p-4 text-center"><div class="mb-3">${avatar(d.fullName,'teal').replace('avatar teal','avatar avatar-lg teal')}</div><h2 class="h4 section-title mb-1">${esc(d.fullName)}</h2><p class="text-secondary mb-3">${esc(d.branch)} · Year ${d.academicYear}</p>${status(d.availability)}<div class="d-flex justify-content-between align-items-center mt-4"><span class="small text-secondary">Profile completion</span><strong class="profile-completion">${d.profileCompletion}%</strong></div><div class="progress profile-progress mt-2"><div class="progress-bar" style="width:${d.profileCompletion}%"></div></div></div></div><div class="col-lg-8"><div class="surface p-4"><h2 class="h5 section-title">About</h2><p class="text-secondary">${esc(d.bio || 'No introduction yet. Add a few details so teammates know what you enjoy working on.')}</p><hr><h2 class="h6 section-title">Skills</h2><div>${d.skills?.length?skills(d.skills):'<span class="text-secondary">No skills added yet.</span>'}</div><h2 class="h6 section-title mt-4">Interests and preferred domains</h2><p class="text-secondary mb-0">${esc(d.interests || 'No interests added yet.')}</p></div></div></div></div></section>`;}catch(e){renderFailure(e);} }

  async function editProfile() { if(!requireAuth())return; busy(); try { const [d,known]=await Promise.all([api('/students/me'),api('/skills')]); app.innerHTML=`${head('Make your profile useful','Specific skills and availability help the right project owner find you.')}<section class="page-main"><div class="container"><div class="row justify-content-center"><div class="col-xl-9"><form id="profile-form" class="surface p-4 p-md-5" novalidate><datalist id="skill-list">${known.map(x=>`<option value="${esc(x)}">`).join('')}</datalist><div class="row g-3"><div class="col-md-6"><label class="form-label">Full name</label><input class="form-control" name="fullName" value="${esc(d.fullName)}" required></div><div class="col-md-6"><label class="form-label">Department or branch</label><input class="form-control" name="branch" value="${esc(d.branch)}" required></div><div class="col-md-4"><label class="form-label">Academic year</label><select class="form-select" name="academicYear">${[1,2,3,4,5].map(x=>`<option ${x===d.academicYear?'selected':''} value="${x}">Year ${x}</option>`).join('')}</select></div><div class="col-md-8"><label class="form-label">Availability</label><select class="form-select" name="availability">${['AVAILABLE','LIMITED','UNAVAILABLE'].map(x=>`<option ${x===d.availability?'selected':''} value="${x}">${nice(x)}</option>`).join('')}</select><div class="form-text">Unavailable students are not recommended for active recruitment.</div></div><div class="col-12"><label class="form-label">About you</label><textarea class="form-control" name="bio" rows="4" maxlength="1200" placeholder="What kinds of projects do you enjoy and what do you bring to a team?">${esc(d.bio||'')}</textarea></div><div class="col-12"><label class="form-label">Interests or preferred domains</label><input class="form-control" name="interests" value="${esc(d.interests||'')}" placeholder="e.g. EdTech, accessibility, sustainability"></div></div><hr class="my-4"><div class="d-flex justify-content-between align-items-center"><div><h2 class="h5 section-title mb-1">Technical skills</h2><p class="text-secondary small mb-0">Add each skill once and choose your current comfort level.</p></div><button type="button" id="add-skill" class="btn btn-soft btn-sm"><i class="bi bi-plus-lg me-1"></i>Add skill</button></div><div id="skill-rows" class="mt-3">${(d.skills||[]).map(s=>skillRow(s.name,s.proficiency)).join('')}</div><div class="d-flex justify-content-end gap-2 mt-4"><a class="btn btn-outline-primary" href="profile.html">Cancel</a><button class="btn btn-primary" type="submit">Save profile</button></div></form></div></div></div></section>`; bindProfileForm(); }catch(e){renderFailure(e);} }
  const skillRow = (name='',level='INTERMEDIATE') => `<div class="row g-2 align-items-center skill-row mb-2"><div class="col-md-7"><input class="form-control skill-name" list="skill-list" value="${esc(name)}" placeholder="e.g. Spring Boot" aria-label="Skill name"></div><div class="col-md-4"><select class="form-select skill-level" aria-label="Skill proficiency">${['BEGINNER','INTERMEDIATE','ADVANCED'].map(x=>`<option ${x===level?'selected':''} value="${x}">${nice(x)}</option>`).join('')}</select></div><div class="col-md-1"><button class="btn btn-danger-soft remove-skill" type="button" aria-label="Remove skill"><i class="bi bi-trash"></i></button></div></div>`;
  function bindProfileForm(){ $('#add-skill')?.addEventListener('click',()=>$('#skill-rows').insertAdjacentHTML('beforeend',skillRow())); $('#skill-rows')?.addEventListener('click',e=>{if(e.target.closest('.remove-skill'))e.target.closest('.skill-row').remove();}); $('#profile-form')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;if(!form.checkValidity()){form.classList.add('was-validated');return;}const b=$('button[type=submit]',form);setButtonBusy(b,true);const d=new FormData(form);const skills=[...form.querySelectorAll('.skill-row')].map(row=>({name:$('.skill-name',row).value.trim(),proficiency:$('.skill-level',row).value})).filter(x=>x.name);try{const updated=await api('/students/me',{method:'PUT',body:JSON.stringify({...Object.fromEntries(d.entries()),academicYear:Number(d.get('academicYear')),skills})});localStorage.setItem('teamfinder.user',JSON.stringify(updated));toast('Your profile has been updated.');go('profile.html');}catch(err){showError(err,form);}finally{setButtonBusy(b,false);}});}

  async function projects() { if(!requireAuth()) return; const params=query(); const state={q:params.get('q')||'',category:params.get('category')||'',status:params.get('status')||'',skill:params.get('skill')||'',branch:params.get('branch')||'',page:params.get('page')||0}; busy(); try { const d=await api(`/projects?${qs({...state,size:9})}`); app.innerHTML=`${head('Explore project opportunities','Find a project that needs your strengths — or get inspired to create a well-scoped brief of your own.',!isAdmin()?'<a class="btn btn-primary" href="create-project.html"><i class="bi bi-plus-lg me-1"></i>Create a project</a>':'')}<section class="page-main"><div class="container"><form id="project-filters" class="surface filter-card mb-4"><div class="row g-2"><div class="col-lg-4"><label class="visually-hidden" for="q">Search</label><div class="input-group"><span class="input-group-text"><i class="bi bi-search"></i></span><input id="q" name="q" class="form-control" value="${esc(state.q)}" placeholder="Search projects or categories"></div></div><div class="col-sm-6 col-lg-2"><select class="form-select" name="status"><option value="">All statuses</option>${['OPEN_FOR_MEMBERS','IN_PROGRESS','TEAM_FULL','DRAFT','COMPLETED'].map(x=>`<option ${state.status===x?'selected':''} value="${x}">${nice(x)}</option>`).join('')}</select></div><div class="col-sm-6 col-lg-2"><input class="form-control" name="category" value="${esc(state.category)}" placeholder="Category"></div><div class="col-sm-6 col-lg-2"><input class="form-control" name="skill" value="${esc(state.skill)}" placeholder="Required skill"></div><div class="col-sm-6 col-lg-2"><button class="btn btn-primary w-100" type="submit">Apply filters</button></div></div></form><div class="d-flex justify-content-between align-items-center mb-3"><span class="text-secondary small">${d.totalElements} project${d.totalElements===1?'':'s'} found</span><a class="small" href="projects.html">Clear filters</a></div>${projectsGrid(d.content)}${pageNumbers(d)}</div></section>`; $('#project-filters').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.currentTarget);go(`projects.html?${qs({...Object.fromEntries(d.entries()),page:0})}`);}); app.querySelectorAll('[data-page-number]').forEach(btn=>btn.addEventListener('click',()=>go(`projects.html?${qs({...state,page:btn.dataset.pageNumber})}`))); }catch(e){renderFailure(e);} }

  async function projectDetail(){ if(!requireAuth())return; const id=query().get('id');if(!id){go('not-found.html');return;}busy();try{const p=await api(`/projects/${id}`);const mine=p.ownerId===user().id;const member=mine||p.members.some(m=>m.studentId===user().id); const actions=mine?`<a class="btn btn-primary" href="candidates.html?id=${p.id}"><i class="bi bi-stars me-1"></i>Find matches</a><a class="btn btn-outline-primary" href="edit-project.html?id=${p.id}">Edit project</a>`:member?`<a class="btn btn-primary" href="workspace.html?id=${p.id}"><i class="bi bi-kanban me-1"></i>Open workspace</a>`:'';app.innerHTML=`${head(p.title,p.shortDescription,actions)}<section class="page-main"><div class="container"><div class="row g-4"><div class="col-lg-8"><article class="surface p-4 mb-4"><div class="d-flex justify-content-between gap-3 flex-wrap mb-4"><div>${status(p.status)}<span class="ms-2 text-secondary small">${esc(p.category)}</span></div><span class="text-secondary small"><i class="bi bi-calendar3 me-1"></i>Updated ${formatDate(p.updatedAt)}</span></div><h2 class="h5 section-title">Project brief</h2><p class="mb-0 text-secondary" style="white-space:pre-line">${esc(p.description)}</p></article><article class="surface p-4 mb-4"><h2 class="h5 section-title">Team</h2><div class="row g-3 mt-1">${p.members.map((m,i)=>`<div class="col-md-6"><div class="d-flex gap-2 align-items-center"><span>${avatar(m.name,i%2?'teal':'')}</span><div><strong class="d-block">${esc(m.name)}</strong><span class="small text-secondary">${esc(nice(m.role))}</span></div></div></div>`).join('')}</div></article></div><aside class="col-lg-4"><div class="surface p-4 mb-3"><p class="section-label mb-2">Team capacity</p><div class="d-flex align-items-end justify-content-between"><strong class="display-6 fw-bold text-primary mb-0">${p.currentTeamSize}/${p.teamSize}</strong><span class="small text-secondary">${p.remainingSlots} slot${p.remainingSlots===1?'':'s'} left</span></div><div class="progress mt-3"><div class="progress-bar" style="width:${Math.min(100,100*p.currentTeamSize/p.teamSize)}%"></div></div></div><div class="surface p-4 mb-3"><p class="section-label mb-2">Skill coverage</p><h2 class="h6 section-title">Needed for this project</h2>${skills(p.skills)}<hr><div class="d-flex gap-2 align-items-center">${avatar(p.ownerName,'warm')}<div><span class="small text-secondary d-block">Project owner</span><strong>${esc(p.ownerName)}</strong></div></div></div>${member?`<a class="btn btn-teal w-100" href="workspace.html?id=${p.id}"><i class="bi bi-kanban me-1"></i>Go to team workspace</a>`:''}</aside></div></div></section>`;}catch(e){renderFailure(e);} }
  const formatDate = date => date ? new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',year:'numeric'}).format(new Date(date)) : 'recently';

  async function projectForm(edit=false){if(!requireAuth())return;const id=query().get('id');if(edit&&!id){go('not-found.html');return;}busy();try{const [p,known]=await Promise.all([edit?api(`/projects/${id}`):Promise.resolve(null),api('/skills')]);if(p&&p.ownerId!==user().id){go('unauthorized.html');return;}app.innerHTML=`${head(edit?'Refine your project brief':'Create a project brief',edit?'Keep requirements clear so the matching results stay trustworthy.':'A focused brief attracts the right collaborators and makes matching more useful.')}<section class="page-main"><div class="container"><div class="row justify-content-center"><div class="col-xl-10"><form id="project-form" class="surface p-4 p-md-5" novalidate><datalist id="project-skill-list">${known.map(x=>`<option value="${esc(x)}">`).join('')}</datalist><div class="row g-3"><div class="col-md-8"><label class="form-label">Project title</label><input class="form-control" name="title" maxlength="140" required value="${esc(p?.title||'')}" placeholder="e.g. Accessible Campus Navigator"><div class="invalid-feedback">Give your project a clear title.</div></div><div class="col-md-4"><label class="form-label">Project category</label><input class="form-control" name="category" maxlength="100" required value="${esc(p?.category||'')}" placeholder="e.g. EdTech"></div><div class="col-md-8"><label class="form-label">Short description</label><input class="form-control" name="shortDescription" maxlength="350" required value="${esc(p?.shortDescription||'')}" placeholder="A crisp summary that helps students decide whether to read on."></div><div class="col-md-4"><label class="form-label">Total team size</label><input class="form-control" name="teamSize" min="2" max="20" type="number" required value="${p?.teamSize||4}"></div><div class="col-12"><label class="form-label">Detailed description</label><textarea class="form-control" name="description" rows="6" maxlength="5000" required placeholder="What problem are you solving? What will the team deliver? What does success look like?">${esc(p?.description||'')}</textarea></div><div class="col-md-6"><label class="form-label">Project status</label><select class="form-select" name="status">${['DRAFT','OPEN_FOR_MEMBERS','IN_PROGRESS','COMPLETED'].map(x=>`<option value="${x}" ${(p?.status||'OPEN_FOR_MEMBERS')===x?'selected':''}>${nice(x)}</option>`).join('')}</select></div></div><hr class="my-4"><div class="d-flex justify-content-between align-items-center"><div><h2 class="h5 section-title mb-1">Required and preferred skills</h2><p class="small text-secondary mb-0">Required skills drive 80% of the match score. Add at least one.</p></div><button type="button" id="add-project-skill" class="btn btn-soft btn-sm"><i class="bi bi-plus-lg me-1"></i>Add skill</button></div><div id="project-skill-rows" class="mt-3">${(p?.skills||[{name:'',skillType:'REQUIRED'}]).map(s=>projectSkillRow(s.name,s.skillType)).join('')}</div><div class="d-flex justify-content-end gap-2 mt-4">${edit?'<button id="archive-project" type="button" class="btn btn-danger-soft me-auto">Archive project</button>':''}<a href="${edit?`project.html?id=${id}`:'dashboard.html'}" class="btn btn-outline-primary">Cancel</a><button class="btn btn-primary" type="submit">${edit?'Save changes':'Publish project'}</button></div></form></div></div></div></section>`;bindProjectForm(edit,id);}catch(e){renderFailure(e);}}
  const projectSkillRow=(name='',type='REQUIRED')=>`<div class="row g-2 align-items-center project-skill-row mb-2"><div class="col-md-7"><input class="form-control project-skill-name" list="project-skill-list" value="${esc(name)}" placeholder="e.g. Java" aria-label="Skill name"></div><div class="col-md-4"><select class="form-select project-skill-type" aria-label="Requirement level"><option ${type==='REQUIRED'?'selected':''} value="REQUIRED">Required</option><option ${type==='PREFERRED'?'selected':''} value="PREFERRED">Preferred</option></select></div><div class="col-md-1"><button type="button" class="btn btn-danger-soft remove-project-skill" aria-label="Remove skill"><i class="bi bi-trash"></i></button></div></div>`;
  function bindProjectForm(edit,id){$('#add-project-skill')?.addEventListener('click',()=>$('#project-skill-rows').insertAdjacentHTML('beforeend',projectSkillRow()));$('#project-skill-rows')?.addEventListener('click',e=>{if(e.target.closest('.remove-project-skill'))e.target.closest('.project-skill-row').remove();});$('#project-form')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;if(!form.checkValidity()){form.classList.add('was-validated');return;}const d=new FormData(form), skills=[...form.querySelectorAll('.project-skill-row')].map(x=>({name:$('.project-skill-name',x).value.trim(),skillType:$('.project-skill-type',x).value})).filter(x=>x.name);if(!skills.length){toast('Add at least one project skill.','danger');return;}const b=$('button[type=submit]',form);setButtonBusy(b,true,edit?'Saving…':'Publishing…');try{const out=await api(edit?`/projects/${id}`:'/projects',{method:edit?'PUT':'POST',body:JSON.stringify({...Object.fromEntries(d.entries()),teamSize:Number(d.get('teamSize')),skills})});toast(edit?'Project updated.':'Project published.');go(`project.html?id=${out.id}`);}catch(err){showError(err,form);}finally{setButtonBusy(b,false);}});$('#archive-project')?.addEventListener('click',async()=>{if(!confirm('Archive this project? It will no longer be available for recruitment.'))return;try{await api(`/projects/${id}/archive`,{method:'POST'});toast('Project archived.');go('dashboard.html');}catch(e){showError(e);}});}

  async function candidates(){if(!requireAuth())return;const id=query().get('id');if(!id){go('not-found.html');return;}busy();try{const [p,list]=await Promise.all([api(`/projects/${id}`),api(`/projects/${id}/candidates`)]);if(p.ownerId!==user().id){go('unauthorized.html');return;}app.innerHTML=`${head('Candidate matches',`Recommendations for ${p.title}. The score weighs required skills most heavily, then preferred skills and project-domain interest.`,`<a class="btn btn-outline-primary" href="project.html?id=${p.id}"><i class="bi bi-arrow-left me-1"></i>Project details</a>`)}<section class="page-main"><div class="container"><div class="callout mb-4"><strong>${p.remainingSlots} team slot${p.remainingSlots===1?'':'s'} remaining.</strong> Candidates who are already members, unavailable, or currently invited are automatically excluded.</div>${list.length?`<div class="row g-3">${list.map((c,i)=>`<article class="col-lg-6"><div class="surface p-4 h-100"><div class="d-flex gap-3"><div>${avatar(c.name,i%2?'teal':'')}</div><div class="flex-grow-1"><div class="d-flex justify-content-between gap-2"><div><h2 class="h5 section-title mb-1">${esc(c.name)}</h2><p class="small text-secondary mb-2">${esc(c.branch)} · Year ${c.academicYear}</p></div><span class="badge bg-primary align-self-start">${c.matchPercentage}% match</span></div><p class="text-secondary small mb-3">${esc(c.explanation)}</p><div class="mb-2"><span class="small fw-bold d-block mb-1">Matching skills</span>${c.matchingSkills.length?skills(c.matchingSkills):'<span class="small text-secondary">No direct skill match</span>'}</div>${c.missingSkills.length?`<div class="mb-3"><span class="small fw-bold d-block mb-1">Still missing</span>${c.missingSkills.map(x=>`<span class="skill-chip">${esc(x)}</span>`).join('')}</div>`:''}<button class="btn btn-teal btn-sm invite" data-student="${c.studentId}"><i class="bi bi-send me-1"></i>Send invitation</button></div></div></div></article>`).join('')}</div>`:empty('person-x','No suitable candidates found','There are no available students with an active skill or interest match right now. Refine your required skills, or try again later.','<a href="edit-project.html?id='+p.id+'" class="btn btn-primary">Refine project requirements</a>')}</div></section>`;app.querySelectorAll('.invite').forEach(b=>b.addEventListener('click',async()=>{setButtonBusy(b,true,'Sending…');try{await api(`/projects/${id}/invitations`,{method:'POST',body:JSON.stringify({studentId:Number(b.dataset.student)})});toast('Invitation sent.');b.closest('article').remove();if(!app.querySelector('.invite'))go(`candidates.html?id=${id}`);}catch(e){showError(e);}finally{setButtonBusy(b,false);}}));}catch(e){renderFailure(e);}}

  async function invitations(){if(!requireAuth())return;busy();try{const list=await api('/invitations');app.innerHTML=`${head('Team invitations','Decide which opportunities make sense for your time, skills, and learning goals.')}<section class="page-main"><div class="container"><div class="row justify-content-center"><div class="col-xl-9">${list.length?`<div class="surface p-3 p-md-4">${list.map(r=>`<div class="list-group-item invitation" data-id="${r.id}"><div class="d-flex flex-column flex-md-row justify-content-between gap-3"><div><div class="d-flex gap-2 align-items-center mb-1"><h2 class="h6 section-title mb-0">${esc(r.projectTitle)}</h2>${status(r.status)}</div><p class="small text-secondary mb-1">Invitation from ${esc(r.fromStudentName)} · Sent ${formatDate(r.createdAt)}</p><a class="small fw-bold" href="project.html?id=${r.projectId}">View project brief <i class="bi bi-arrow-right"></i></a></div>${r.status==='PENDING'?`<div class="d-flex gap-2 flex-shrink-0"><button class="btn btn-outline-primary btn-sm reject">Decline</button><button class="btn btn-primary btn-sm accept">Accept invitation</button></div>`:''}</div></div>`).join('')}</div>`:empty('envelope-open','No invitations waiting','When a project owner thinks you are a good fit, their invitation will appear here.','<a href="projects.html" class="btn btn-primary">Explore projects</a>')}</div></div></div></section>`;app.querySelectorAll('.accept,.reject').forEach(button=>button.addEventListener('click',async()=>{const root=button.closest('.invitation');const accept=button.classList.contains('accept');setButtonBusy(button,true,accept?'Accepting…':'Declining…');try{await api(`/invitations/${root.dataset.id}/${accept?'accept':'reject'}`,{method:'POST'});toast(accept?'You joined the project team.':'Invitation declined.');invitations();}catch(e){showError(e);}finally{setButtonBusy(button,false);}}));}catch(e){renderFailure(e);}}

  async function workspace(){if(!requireAuth())return;const id=query().get('id');if(!id){go('not-found.html');return;}busy();try{const d=await api(`/projects/${id}/workspace`);app.innerHTML=`${head(d.project.title,'A focused space for your team’s next commitments and shared progress.','<a class="btn btn-outline-primary" href="project.html?id='+d.project.id+'"><i class="bi bi-arrow-left me-1"></i>Project details</a>')}<section class="page-main"><div class="container"><div class="row g-4"><div class="col-lg-8"><div class="surface p-4 mb-4"><div class="d-flex justify-content-between align-items-center mb-3"><div><p class="section-label mb-1">Project progress</p><h2 class="h5 section-title mb-0">${d.progressPercentage}% complete</h2></div>${status(d.project.status)}</div><div class="progress" style="height:12px"><div class="progress-bar" style="width:${d.progressPercentage}%"></div></div></div><div class="surface p-4"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h5 section-title mb-0">Milestones</h2><button class="btn btn-soft btn-sm" data-bs-toggle="collapse" data-bs-target="#milestone-form"><i class="bi bi-plus-lg me-1"></i>Add milestone</button></div><form id="milestone-form" class="collapse border rounded-3 p-3 mb-3" novalidate><div class="row g-2"><div class="col-md-6"><label class="form-label">Title</label><input name="title" class="form-control" required maxlength="150"></div><div class="col-md-3"><label class="form-label">Due date</label><input name="dueDate" type="date" class="form-control"></div><div class="col-md-3"><label class="form-label">Status</label><select name="status" class="form-select">${['NOT_STARTED','IN_PROGRESS','COMPLETED','BLOCKED'].map(x=>`<option value="${x}">${nice(x)}</option>`).join('')}</select></div><div class="col-md-9"><label class="form-label">Description</label><input name="description" class="form-control" maxlength="2000"></div><div class="col-md-3"><label class="form-label">Progress %</label><input name="progressPercentage" type="number" min="0" max="100" value="0" class="form-control"></div></div><button class="btn btn-primary btn-sm mt-3" type="submit">Add milestone</button></form>${d.milestones.length?`<div class="list-group list-group-flush">${d.milestones.map(m=>`<div class="list-group-item"><div class="d-flex justify-content-between gap-3"><div><div class="d-flex gap-2 align-items-center"><strong>${esc(m.title)}</strong>${status(m.status)}</div><p class="small text-secondary mb-1">${esc(m.description||'No description')} ${m.dueDate?'· Due '+formatDate(m.dueDate):''}</p></div><strong class="text-primary">${m.progressPercentage}%</strong></div><div class="progress mt-2"><div class="progress-bar" style="width:${m.progressPercentage}%"></div></div></div>`).join('')}</div>`:empty('flag','No milestones yet','Create a milestone to make the first commitment visible to the team.')}</div></div><aside class="col-lg-4"><div class="surface p-4 mb-3"><h2 class="h6 section-title">Team members</h2>${d.project.members.map((m,i)=>`<div class="d-flex gap-2 align-items-center py-2"><span>${avatar(m.name,i%2?'teal':'')}</span><span><strong class="small d-block">${esc(m.name)}</strong><span class="small text-secondary">${esc(nice(m.role))}</span></span></div>`).join('')}</div><div class="surface p-4"><h2 class="h6 section-title">Recent activity</h2>${d.activities.length?d.activities.map(a=>`<div class="activity-item pb-3"><strong class="small d-block">${esc(a.message)}</strong><span class="small text-secondary">${formatDate(a.createdAt)}</span></div>`).join(''):'<p class="small text-secondary mb-0">Activity will appear as the team begins working.</p>'}</div></aside></div></div></section>`;$('#milestone-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget;if(!f.checkValidity()){f.classList.add('was-validated');return;}const b=$('button[type=submit]',f);setButtonBusy(b,true,'Adding…');try{const v=Object.fromEntries(new FormData(f).entries());v.progressPercentage=Number(v.progressPercentage);await api(`/projects/${id}/milestones`,{method:'POST',body:JSON.stringify(v)});toast('Milestone added.');workspace();}catch(err){showError(err,f);}finally{setButtonBusy(b,false);}});}catch(e){renderFailure(e);}}

  async function adminDashboard(){if(!requireAuth(true))return;busy();try{const s=await api('/admin/stats');const bar=(obj,emptyText)=>Object.keys(obj).length?`<div class="kpi-chart">${Object.entries(obj).slice(0,7).map(([k,v])=>`<div class="kpi-bar" title="${esc(k)}: ${v}" style="height:${Math.max(20,Math.min(100,Number(v)*28))}%"><span>${esc(k)}</span></div>`).join('')}</div>`:`<p class="small text-secondary mb-0">${emptyText}</p>`;app.innerHTML=`${head('Platform overview','A concise operational view of student activity, team formation, and project moderation.','<div class="d-flex gap-2"><a href="admin-users.html" class="btn btn-outline-primary">Manage students</a><a href="admin-projects.html" class="btn btn-primary">Manage projects</a></div>')}<section class="page-main"><div class="container"><div class="row g-3 mb-4"><div class="col-sm-6 col-xl-3">${metric('bi-mortarboard', 'Students',s.totalStudents,'')}</div><div class="col-sm-6 col-xl-3">${metric('bi-briefcase', 'Active projects',s.activeProjects,'success')}</div><div class="col-sm-6 col-xl-3">${metric('bi-door-open','Open projects',s.openProjects,'warning')}</div><div class="col-sm-6 col-xl-3">${metric('bi-envelope','Pending requests',s.pendingRequests,'danger')}</div></div><div class="row g-4"><div class="col-lg-6"><div class="surface p-4 h-100"><h2 class="h5 section-title">Most common skills</h2><p class="small text-secondary">Skills represented across student profiles.</p>${bar(s.mostCommonSkills,'No student skills available yet.')}</div></div><div class="col-lg-6"><div class="surface p-4 h-100"><h2 class="h5 section-title">Projects by category</h2><p class="small text-secondary">A quick indication of where students are building.</p>${bar(s.projectsByCategory,'No projects available yet.')}</div></div></div></div></section>`;}catch(e){renderFailure(e);}}

  async function adminUsers(){if(!requireAuth(true))return;const params=query(),q=params.get('q')||'',pg=params.get('page')||0;busy();try{const d=await api(`/admin/users?${qs({q,page:pg,size:15})}`);app.innerHTML=`${head('Manage students','Search profiles and adjust availability when a profile needs moderation.')}<section class="page-main"><div class="container"><form id="admin-user-search" class="surface filter-card mb-4"><div class="row g-2"><div class="col-md-9"><label class="visually-hidden">Search students</label><input class="form-control" name="q" value="${esc(q)}" placeholder="Search by student name"></div><div class="col-md-3"><button class="btn btn-primary w-100">Search</button></div></div></form><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Student</th><th>Branch</th><th>Year</th><th>Skills</th><th>Availability</th></tr></thead><tbody>${d.content.map(s=>`<tr><td><div class="d-flex gap-2 align-items-center">${avatar(s.fullName)}<span><strong class="d-block">${esc(s.fullName)}</strong><small class="text-secondary">${esc(s.email)}</small></span></div></td><td>${esc(s.branch)}</td><td>${s.academicYear}</td><td>${(s.skills||[]).slice(0,3).map(x=>`<span class="skill-chip">${esc(x.name)}</span>`).join('')}</td><td><select class="form-select form-select-sm availability" data-id="${s.id}">${['AVAILABLE','LIMITED','UNAVAILABLE'].map(x=>`<option ${x===s.availability?'selected':''} value="${x}">${nice(x)}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div>${pageNumbers(d)}</div></section>`;$('#admin-user-search').addEventListener('submit',e=>{e.preventDefault();go(`admin-users.html?${qs({...Object.fromEntries(new FormData(e.currentTarget).entries()),page:0})}`);});app.querySelectorAll('.availability').forEach(x=>x.addEventListener('change',async()=>{try{await api(`/admin/users/${x.dataset.id}/availability?availability=${x.value}`,{method:'PATCH'});toast('Availability updated.');}catch(e){showError(e);}}));app.querySelectorAll('[data-page-number]').forEach(x=>x.addEventListener('click',()=>go(`admin-users.html?${qs({q,page:x.dataset.pageNumber})}`)));}catch(e){renderFailure(e);}}

  async function adminProjects(){if(!requireAuth(true))return;const params=query(),q=params.get('q')||'',statusFilter=params.get('status')||'',pg=params.get('page')||0;busy();try{const d=await api(`/admin/projects?${qs({q,status:statusFilter,page:pg,size:15})}`);app.innerHTML=`${head('Manage projects','Review project posts and set an appropriate lifecycle status where moderation is needed.')}<section class="page-main"><div class="container"><form id="admin-project-search" class="surface filter-card mb-4"><div class="row g-2"><div class="col-md-7"><input class="form-control" name="q" value="${esc(q)}" placeholder="Search by title or category"></div><div class="col-md-3"><select class="form-select" name="status"><option value="">All statuses</option>${['DRAFT','OPEN_FOR_MEMBERS','TEAM_FULL','IN_PROGRESS','COMPLETED','ARCHIVED'].map(x=>`<option ${statusFilter===x?'selected':''} value="${x}">${nice(x)}</option>`).join('')}</select></div><div class="col-md-2"><button class="btn btn-primary w-100">Filter</button></div></div></form><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Project</th><th>Owner</th><th>Team</th><th>Current status</th><th>Moderate status</th></tr></thead><tbody>${d.content.map(p=>`<tr><td><a class="fw-bold" href="project.html?id=${p.id}">${esc(p.title)}</a><small class="d-block text-secondary">${esc(p.category)}</small></td><td>${esc(p.ownerName)}</td><td>${p.currentTeamSize}/${p.teamSize}</td><td>${status(p.status)}</td><td><select class="form-select form-select-sm project-status" data-id="${p.id}">${['DRAFT','OPEN_FOR_MEMBERS','TEAM_FULL','IN_PROGRESS','COMPLETED','ARCHIVED'].map(x=>`<option ${x===p.status?'selected':''} value="${x}">${nice(x)}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div>${pageNumbers(d)}</div></section>`;$('#admin-project-search').addEventListener('submit',e=>{e.preventDefault();go(`admin-projects.html?${qs({...Object.fromEntries(new FormData(e.currentTarget).entries()),page:0})}`);});app.querySelectorAll('.project-status').forEach(x=>x.addEventListener('change',async()=>{if(x.value==='ARCHIVED'&&!confirm('Archive this project? It will be removed from active recruitment.')){adminProjects();return;}try{await api(`/admin/projects/${x.dataset.id}/status?status=${x.value}`,{method:'PATCH'});toast('Project status updated.');}catch(e){showError(e);}}));app.querySelectorAll('[data-page-number]').forEach(x=>x.addEventListener('click',()=>go(`admin-projects.html?${qs({q,status:statusFilter,page:x.dataset.pageNumber})}`)));}catch(e){renderFailure(e);}}

  function simpleError(kind){const notFound=kind==='not-found';app.innerHTML=`<section class="unauthorized"><div class="container"><div class="code">${notFound?'404':'403'}</div><h1 class="section-title">${notFound?'This page is taking a study break.':'This area is reserved for a different role.'}</h1><p class="text-secondary mx-auto" style="max-width:480px">${notFound?'The link may be outdated, or the page may have moved.':'Your account does not have permission to view this page. You can continue with the parts of TeamFinder available to you.'}</p><a class="btn btn-primary mt-2" href="${user()?(isAdmin()?'admin.html':'dashboard.html'):'index.html'}">Back to a safe place</a></div></section>`;}
  function renderFailure(e){app.innerHTML=`<section class="page-main"><div class="container"><div class="row justify-content-center"><div class="col-lg-7">${empty('exclamation-triangle','We could not load this page',e.message || 'Please try again in a moment.','<button class="btn btn-primary" onclick="location.reload()">Try again</button>')}</div></div></div></section>`;}

  function init(){nav();footer();const routes={landing,login:()=>{authPage('login');bindAuth('login');},register:()=>{authPage('register');bindAuth('register');},dashboard,profile,'edit-profile':editProfile,projects,project:projectDetail,'create-project':()=>projectForm(false),'edit-project':()=>projectForm(true),candidates,invitations,workspace,admin:adminDashboard,'admin-users':adminUsers,'admin-projects':adminProjects,unauthorized:()=>simpleError('unauthorized'),'not-found':()=>simpleError('not-found')};(routes[page]||routes['not-found'])();}
  init();
})();
